import json,pathlib,subprocess,hashlib
root=pathlib.Path('/tmp/drumee-il59b-debian-clean');e=pathlib.Path('/tmp/drumee-il59b-evidence');r=json.loads((e/'images-first.json').read_text());source=json.loads((root/'profiles/minimal-application/infra-source-lock.json').read_text())
def docker(*args,**kw):return subprocess.check_output(['docker',*args],text=True,**kw)
app=json.loads(docker('image','inspect',r['image']))[0]; tools=json.loads(docker('image','inspect',r['tools']['image']))[0]
a=app['Config']['Labels'];t=tools['Config']['Labels'];assert a['org.opencontainers.image.revision']==r['revision'];assert a['org.drumee.infra.revision']==source['revision'];assert a['org.drumee.infra.source-integrity']==source['integrity'];assert t['org.opencontainers.image.revision']==source['revision'];assert app['Config']['User']=='1000:1000'
script="""const fs=require('node:fs'),crypto=require('node:crypto');const hashes={};function walk(p,prefix=''){for(const n of fs.readdirSync(p)){const f=p+'/'+n;if(fs.statSync(f).isDirectory())walk(f,prefix+n+'/');else hashes[prefix+n]=crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex')}}walk('/app/node_modules/@drumee/server-runtime');console.log(JSON.stringify({version:JSON.parse(fs.readFileSync('/app/node_modules/@drumee/server-runtime/package.json')).version,runtime_files:hashes,host:crypto.createHash('sha256').update(fs.readFileSync('/app/host.js')).digest('hex'),health:crypto.createHash('sha256').update(fs.readFileSync('/app/health.js')).digest('hex'),worker:crypto.createHash('sha256').update(fs.readFileSync('/app/plugins/qualification/server/worker.js')).digest('hex'),plugins:JSON.parse(fs.readFileSync('/app/plugins-manifest.json')),artifact:JSON.parse(fs.readFileSync('/app/plugins/qualification/.drumee-artifact.json')),infra:fs.existsSync('/app/node_modules/@drumee/infra-layer'),eslint:fs.existsSync('/app/node_modules/eslint')}));"""
x=json.loads(docker('run','--rm','--network','none','--label','org.drumee.il59b.owner=qualification',r['image'],'node','-e',script))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
runtime=root/'profiles/minimal-application/node_modules/@drumee/server-runtime';expected={str(p.relative_to(runtime)):sha(p) for p in runtime.rglob('*') if p.is_file()};assert x['runtime_files']==expected;assert x['version']=='0.1.0-alpha.4';assert x['plugins']==r['plugins'];assert x['host']==sha(root/'profiles/minimal-application/runtime/host.js');assert x['health']==sha(root/'profiles/minimal-application/runtime/health.js');assert x['worker']==sha(root/'tests/minimal-application/fixtures/plugin/server/worker.js');assert not x['infra'] and not x['eslint'];assert x['artifact']['integrity']==r['artifacts'][0]['integrity'];assert x['artifact']['revision']==r['revision']
versions=docker('run','--rm','--network','none','--label','org.drumee.il59b.owner=qualification','--entrypoint','dpkg-query',r['tools']['image'],'-W','-f=${Package}=${Version}\n','postfix','opendkim','bind9','openssl').splitlines()
assert (e/'images-first.json').read_bytes()==(e/'images-second.json').read_bytes()
result={'status':'passed','build_revision':r['revision'],'same_host_rebuild_receipts_identical':True,'application_image':r['image'],'tools_image':r['tools']['image'],'application_labels':a,'tools_labels':t,'runtime_files_compared':len(expected),'runtime_version':x['version'],'host_health_and_plugin_bytes_match':True,'verified_plugin_artifact':x['artifact'],'production_has_infra_or_eslint':False,'native_tool_versions':versions,'orchestrator_location':'host installed immutable Infra Layer module; not copied into application image'}
(e/'image-verification.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
